-- ==============================================================================
-- P_311: Knowledge-Driven IoT Fault Diagnosis Assistant
-- Database Schema Initialization
-- Persistence layer for fault incidents and streaming sensor telemetry.
-- ==============================================================================

-- 1. Fault Incidents Table
-- Stores historical diagnoses generated by the RAG + LLM inference pipeline.
CREATE TABLE IF NOT EXISTS fault_incidents (
    id BIGSERIAL PRIMARY KEY,
    timestamp TIMESTAMPTZ NOT NULL,
    device_id VARCHAR(64) NOT NULL,
    fault_category VARCHAR(64) NOT NULL,
    symptoms JSONB NOT NULL DEFAULT '[]'::jsonb,
    temperature DOUBLE PRECISION,
    vibration DOUBLE PRECISION,
    pressure DOUBLE PRECISION,
    retrieved_sources JSONB NOT NULL DEFAULT '[]'::jsonb,
    diagnosis_text TEXT,
    likely_fault TEXT,
    why TEXT,
    recommended_checks TEXT,
    confidence_limitations TEXT,
    sections JSONB NOT NULL DEFAULT '{}'::jsonb,
    runtime VARCHAR(64),
    latency_seconds DOUBLE PRECISION,
    created_at TIMESTAMPTZ DEFAULT CURRENT_TIMESTAMP,
    CONSTRAINT uq_fault_incident_device_ts UNIQUE (device_id, timestamp)
);

-- Indexes for fast query retrieval and historical ordering
CREATE INDEX IF NOT EXISTS idx_fault_incidents_timestamp 
    ON fault_incidents (timestamp DESC);

CREATE INDEX IF NOT EXISTS idx_fault_incidents_device_timestamp 
    ON fault_incidents (device_id, timestamp DESC);

CREATE INDEX IF NOT EXISTS idx_fault_incidents_category 
    ON fault_incidents (fault_category);


-- 2. Telemetry Readings Table (Plain Table, No Partitioning)
-- Stores physical sensor readings ingested from the MQTT telemetry stream.
CREATE TABLE IF NOT EXISTS telemetry_readings (
    id BIGSERIAL PRIMARY KEY,
    timestamp TIMESTAMPTZ NOT NULL,
    device_id VARCHAR(64) NOT NULL,
    temperature DOUBLE PRECISION NOT NULL,
    vibration DOUBLE PRECISION NOT NULL,
    pressure DOUBLE PRECISION NOT NULL,
    mode VARCHAR(32) NOT NULL DEFAULT 'normal',
    created_at TIMESTAMPTZ DEFAULT CURRENT_TIMESTAMP
);

-- Indexes for time-series range lookups and device filtering
CREATE INDEX IF NOT EXISTS idx_telemetry_timestamp 
    ON telemetry_readings (timestamp DESC);

CREATE INDEX IF NOT EXISTS idx_telemetry_device_timestamp 
    ON telemetry_readings (device_id, timestamp DESC);


-- 3. Telemetry Retention Pruning Function
-- Called periodically (startup and hourly) to remove telemetry older than the retention threshold.
CREATE OR REPLACE FUNCTION prune_old_telemetry(retention_days INT DEFAULT 7)
RETURNS BIGINT AS $$
DECLARE
    deleted_count BIGINT;
BEGIN
    DELETE FROM telemetry_readings
    WHERE timestamp < (CURRENT_TIMESTAMP - (retention_days || ' days')::INTERVAL);
    GET DIAGNOSTICS deleted_count = ROW_COUNT;
    RETURN deleted_count;
END;
$$ LANGUAGE plpgsql;
